//! Other stores' `ig2.exe` builds seen through the GOG 2017 build's layout (`re/formats/exe-builds.md`).
//!
//! Every rule table is read at its GOG address. The Steam build (linked 2018-04-18) holds the same data at other
//! addresses: [`to_gog_layout`] rebuilds its initialised data sections at the GOG addresses from a segment table
//! (generated by `tools/exe_builds/align.py`) and rewrites each relocated pointer that lands in a mapped place. Of
//! the code only the functions the engine decodes are copied (their calls re-aimed); the rest of the code and the
//! C++ runtime metadata stay zero.

mod steam2018;

struct Build {
    name: &'static str,
    /// PE `TimeDateStamp` and file length: enough to tell the known builds apart.
    stamp: u32,
    len: usize,
    segments: &'static [(u32, u32, u32)],
    /// Call operands in the copied code: (GOG VA of the rel32, GOG VA of the callee).
    calls: &'static [(u32, u32)],
    /// Uninitialised globals the copied code names: (GOG VA, this build's VA).
    globals: &'static [(u32, u32)],
}

const BUILDS: [Build; 1] = [Build {
    name: "Steam 2018-04-18",
    stamp: 0x5ad7_b7b1,
    len: 5_766_144,
    segments: &steam2018::SEGMENTS,
    calls: &steam2018::CALLS,
    globals: &steam2018::GLOBALS,
}];

/// The GOG build's sections in table order: (virtual address, virtual size, raw size, raw offset).
const GOG_SECTIONS: [(u32, u32, u32, u32); 7] = [
    (0x1000, 0x433d74, 0x433e00, 0x400),       // .text
    (0x435000, 0xa8418, 0xa8600, 0x434200),    // .rdata
    (0x4de000, 0x7924e4, 0x55200, 0x4dc800),   // .data
    (0xc71000, 0x900, 0xa00, 0x531a00),        // .rodata
    (0xc72000, 0x8e0, 0xa00, 0x532400),        // _RDATA
    (0xc73000, 0x262c8, 0x26400, 0x532e00),    // .rsrc
    (0xc9a000, 0x3ea68, 0x3ec00, 0x559200),    // .reloc
];
const GOG_LEN: usize = 5_864_960;
const IMAGE_BASE: u32 = 0x40_0000;
/// Written over the DOS stub of a converted image; [`converted_from`] reads it back.
const MARK: &[u8] = b"openIG2 GOG layout of ";

fn u16_at(b: &[u8], o: usize) -> Option<u16> {
    Some(u16::from_le_bytes(b.get(o..o + 2)?.try_into().ok()?))
}

fn u32_at(b: &[u8], o: usize) -> Option<u32> {
    Some(u32::from_le_bytes(b.get(o..o + 4)?.try_into().ok()?))
}

/// The build `exe` is, when it is a known non-GOG build.
fn build_of(exe: &[u8]) -> Option<&'static Build> {
    let pe = u32_at(exe, 0x3c)? as usize;
    let stamp = u32_at(exe, pe + 8)?;
    BUILDS.iter().find(|b| b.stamp == stamp && b.len == exe.len())
}

/// The name of the build a [`to_gog_layout`] image came from.
pub fn converted_from(exe: &[u8]) -> Option<&'static str> {
    let rest = exe.get(0x40..)?.strip_prefix(MARK)?;
    BUILDS.iter().map(|b| b.name).find(|n| rest.starts_with(n.as_bytes()))
}

/// `exe` in the GOG layout when it is a known other build; `None` for the GOG build and unknown ones.
pub fn to_gog_layout(exe: &[u8]) -> Option<Vec<u8>> {
    let build = build_of(exe)?;
    let pe = u32_at(exe, 0x3c)? as usize;
    let nsec = u16_at(exe, pe + 6)? as usize;
    let table = pe + 24 + u16_at(exe, pe + 20)? as usize;
    if nsec != GOG_SECTIONS.len() || MARK.len() + build.name.len() > pe - 0x40 {
        return None;
    }
    // the other build's sections: (va, raw size, raw offset), for VA → file offset
    let theirs: Vec<(u32, u32, u32)> =
        (0..nsec).map(|i| Some((u32_at(exe, table + 40 * i + 12)? + IMAGE_BASE, u32_at(exe, table + 40 * i + 16)?, u32_at(exe, table + 40 * i + 20)?))).collect::<Option<_>>()?;
    let their_off = |va: u32| theirs.iter().find(|s| va >= s.0 && va - s.0 < s.1).map(|s| (s.2 + va - s.0) as usize);
    let gog_off = |va: u32| GOG_SECTIONS.iter().find(|s| va >= s.0 + IMAGE_BASE && va - s.0 - IMAGE_BASE < s.2).map(|s| (s.3 + va - s.0 - IMAGE_BASE) as usize);
    let to_gog = |va: u32| {
        let i = build.segments.partition_point(|s| s.1 + s.2 <= va);
        build.segments.get(i).filter(|s| va >= s.1).map(|s| s.0 + va - s.1).or_else(|| build.globals.iter().find(|g| g.1 == va).map(|g| g.0))
    };

    let mut out = vec![0u8; GOG_LEN];
    out[..0x400].copy_from_slice(exe.get(..0x400)?);
    out[0x40..0x40 + MARK.len()].copy_from_slice(MARK);
    out[0x40 + MARK.len()..0x40 + MARK.len() + build.name.len()].copy_from_slice(build.name.as_bytes());
    for (i, &(va, vsize, rsize, roff)) in GOG_SECTIONS.iter().enumerate() {
        let o = table + 40 * i;
        for (k, v) in [vsize, va, rsize, roff].into_iter().enumerate() {
            out[o + 8 + 4 * k..o + 12 + 4 * k].copy_from_slice(&v.to_le_bytes());
        }
    }
    for &(gva, tva, n) in build.segments {
        let (g, t, n) = (gog_off(gva)?, their_off(tva)?, n as usize);
        out[g..g + n].copy_from_slice(exe.get(t..t + n)?);
    }
    // relocated dwords (base-relocation directory, entry 5): pointers to rewrite into GOG addresses
    let (rva, size) = (u32_at(exe, pe + 24 + 96 + 5 * 8)?, u32_at(exe, pe + 24 + 96 + 5 * 8 + 4)?);
    let (mut at, end) = (their_off(rva + IMAGE_BASE)?, their_off(rva + IMAGE_BASE)? + size as usize);
    while at + 8 <= end {
        let (page, block) = (u32_at(exe, at)?, u32_at(exe, at + 4)? as usize);
        if block < 8 {
            break;
        }
        for k in 0..(block - 8) / 2 {
            let e = u16_at(exe, at + 8 + 2 * k)?;
            if e >> 12 != 3 {
                continue;
            }
            let place = IMAGE_BASE + page + (e & 0xfff) as u32;
            let (Some(gplace), Some(value)) = (to_gog(place), their_off(place).and_then(|o| u32_at(exe, o))) else { continue };
            if let (Some(g), Some(v)) = (gog_off(gplace), to_gog(value)) {
                out[g..g + 4].copy_from_slice(&v.to_le_bytes());
            }
        }
        at += block;
    }
    for &(v, callee) in build.calls {
        let o = gog_off(v)?;
        out[o..o + 4].copy_from_slice(&callee.wrapping_sub(v + 4).to_le_bytes());
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn segments_sorted_and_inside_gog_sections() {
        for b in &BUILDS {
            assert!(b.segments.windows(2).all(|w| w[0].1 + w[0].2 <= w[1].1), "{}", b.name);
            for &(g, _, n) in b.segments {
                assert!(GOG_SECTIONS.iter().any(|s| g >= s.0 + IMAGE_BASE && g + n <= s.0 + IMAGE_BASE + s.2), "{g:#x}");
            }
        }
    }

    #[test]
    fn unknown_builds_pass_through() {
        assert!(to_gog_layout(b"MZ").is_none());
        assert!(converted_from(b"MZ").is_none());
    }
}
